import { createRoot } from "react-dom/client";
import { GraphExplorerApp } from "./GraphExplorerApp.tsx";
import { graphEndpoint, resolveServerIdentity } from "./transport.ts";
import "./graph-explorer.css";

/**
 * The route context the Workbench passes to a route script's mount function (see scriptMount in
 * classic/workbenchRoutes.ts). Only the members the island uses are typed here.
 */
export type GraphRouteContext = {
  context: { basePath: string; repositoryId: string | null; serverIdentity?: string | null };
  model?: { rows?: unknown[]; vars?: string[] } & Record<string, unknown>;
  url?: URL | string;
};

export type GraphExplorerCleanup = () => void;

const STYLESHEET_ATTRIBUTE = "data-graph-explorer-stylesheet";
const FULL_BLEED_CLASS = "workbench-page-surface--full-bleed";
const stylesheetLoads = new WeakMap<Document, Map<string, Promise<void>>>();

/** The explorer's stylesheet is built next to its bundle (styles/graph-explorer.css); share its load per document. */
function ensureStylesheet(document: Document, basePath: string): Promise<void> {
  // Vite injects the static CSS import before evaluating this module in development; the separate file is a production asset.
  if (import.meta.env.DEV) {
    return Promise.resolve();
  }

  const href = new URL(`${basePath.replace(/\/+$/, "")}/styles/graph-explorer.css`, document.baseURI).href;
  let loads = stylesheetLoads.get(document);
  if (!loads) {
    loads = new Map();
    stylesheetLoads.set(document, loads);
  }

  const existing = loads.get(href);
  if (existing) {
    return existing;
  }

  const existingLink = Array.from(document.querySelectorAll<HTMLLinkElement>(`link[${STYLESHEET_ATTRIBUTE}]`))
    .find(link => link.href === href);
  if (existingLink?.sheet) {
    const loaded = Promise.resolve();
    loads.set(href, loaded);
    return loaded;
  }
  existingLink?.remove();

  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = href;
  link.setAttribute(STYLESHEET_ATTRIBUTE, "true");

  let onLoad = () => {};
  let onError = () => {};
  const loaded = new Promise<void>((resolve, reject) => {
    const finish = (error?: Error) => {
      link.removeEventListener("load", onLoad);
      link.removeEventListener("error", onError);
      if (error) {
        loads!.delete(href);
        link.remove();
        reject(error);
      } else {
        resolve();
      }
    };
    onLoad = () => finish();
    onError = () => finish(new Error(`Could not load graph explorer stylesheet: ${href}`));
  });
  loads.set(href, loaded);
  link.addEventListener("load", onLoad);
  link.addEventListener("error", onError);
  document.head.appendChild(link);
  return loaded;
}

function basePathOf(outlet: HTMLElement, ctx?: GraphRouteContext): string {
  if (ctx?.context?.basePath !== undefined) {
    return ctx.context.basePath;
  }
  const app = outlet.ownerDocument.getElementById("workbench-app");
  return app?.getAttribute("data-workbench-base-path") ?? "";
}

function repositoryIdOf(outlet: HTMLElement, ctx?: GraphRouteContext): string | null {
  if (ctx?.context?.repositoryId) {
    return ctx.context.repositoryId;
  }
  const mount = outlet.querySelector<HTMLElement>("[data-graph-explorer-mount]");
  return mount?.dataset.repositoryId || outlet.ownerDocument.getElementById("workbench-app")?.getAttribute("data-workbench-repository-id") || null;
}

/** Mounts the graph explorer into the route outlet and returns the function that unmounts it again. */
export function mount(outlet: HTMLElement, ctx?: GraphRouteContext): GraphExplorerCleanup {
  const document = outlet.ownerDocument;
  const basePath = basePathOf(outlet, ctx);
  const repositoryId = repositoryIdOf(outlet, ctx);
  // A fresh route model is authoritative. An old shell attribute must not replace missing route identity.
  const serverIdentity = ctx ? ctx.context.serverIdentity
    : document.getElementById("workbench-app")?.getAttribute("data-workbench-server-identity");
  const host = outlet.querySelector<HTMLElement>("[data-graph-explorer-mount]") ?? outlet;
  const surface = host.closest<HTMLElement>("#workbench-page-surface, .workbench-page-surface");
  surface?.classList.add(FULL_BLEED_CLASS);
  const container = document.createElement("div");
  container.className = "graph-explorer";
  host.appendChild(container);
  // The explorer fills the viewport below the Workbench page header; the header's height is measured, not assumed,
  // and measured again whenever it changes (a description that wraps, a wider sidebar, a message above the page).
  const view = document.defaultView;
  const sizeToViewport = () => {
    const top = Math.max(0, Math.round(container.getBoundingClientRect().top + (view?.scrollY ?? 0)));
    container.style.setProperty("--graph-explorer-height", `calc(100dvh - ${top}px)`);
  };
  sizeToViewport();
  view?.addEventListener("resize", sizeToViewport);
  const header = typeof ResizeObserver === "function" ? new ResizeObserver(sizeToViewport) : null;
  const outletElement = surface?.parentElement ?? null;
  if (header && outletElement) {
    for (const child of Array.from(outletElement.children)) if (child !== surface) header.observe(child);
  }
  const root = createRoot(container);
  const controller = new AbortController();
  // The Graph servlet's limits, from the page data on the mount (classic/workbenchViews.ts, graphPage).
  const limit = (name: string) => {
    const value = Number(host.dataset[name]);
    return Number.isInteger(value) && value > 0 ? value : undefined;
  };
  const limits = { maxResultRows: limit("maxResultRows"), maxQueryLength: limit("maxQueryLength") };
  const renderExplorer = (identity: string) => root.render(
    <GraphExplorerApp key={identity} basePath={basePath} repositoryId={repositoryId!} serverIdentity={identity} limits={limits} />,
  );
  const renderRoute = () => {
    if (repositoryId && serverIdentity) {
      renderExplorer(serverIdentity);
    } else if (repositoryId) {
      root.render(<p className="workbench-empty">Connecting to the repository…</p>);
      // Vite's development page and direct mounts have no Workbench shell/model. Resolve the manager before creating
      // any persistent scope, keeping these supported entry points identical to an ordinary Graph navigation.
      void resolveServerIdentity(graphEndpoint(basePath, repositoryId), controller.signal)
        .then(identity => { if (!controller.signal.aborted) renderExplorer(identity); })
        .catch(error => { if (!controller.signal.aborted) root.render(<p className="workbench-empty">{error.message}</p>); });
    } else {
      root.render(<p className="workbench-empty">Choose a repository to explore it as a graph.</p>);
    }
  };
  const loadStylesAndRender = () => {
    if (controller.signal.aborted) {
      return;
    }
    root.render(<p className="workbench-empty" role="status">Loading the graph explorer…</p>);
    void ensureStylesheet(document, basePath).then(() => {
      if (!controller.signal.aborted) {
        sizeToViewport();
        renderRoute();
      }
    }).catch(() => {
      if (!controller.signal.aborted) {
        root.render(
          <div className="workbench-empty" role="alert">
            <p>The graph explorer could not be loaded.</p>
            <button type="button" onClick={loadStylesAndRender}>Retry</button>
          </div>,
        );
      }
    });
  };
  loadStylesAndRender();
  return () => {
    controller.abort();
    view?.removeEventListener("resize", sizeToViewport);
    header?.disconnect();
    root.unmount();
    container.remove();
    surface?.classList.remove(FULL_BLEED_CLASS);
  };
}

declare global {
  interface Window {
    workbench?: Record<string, unknown>;
  }
}

if (typeof window !== "undefined") {
  const namespace = (window.workbench ??= {});
  namespace.graphExplorer = { mount };
}
